function selectOption(select) {
    if (!select) {
        return;
    }

    syncSelectors(select.selectedIndex);

    const allOptions = Array.from(select.options);
    const selectedValue = select.options[select.selectedIndex].value;

    // Hide section that isn't selected, and show section that is selected.
    allOptions.forEach((option) => {
        if (option.value === selectedValue) {
            const toShow = document.getElementsByClassName(option.value);
            for (let i = 0; i < toShow.length; i++) {
                toShow[i].classList.remove('hidden');
            }
            return;
        }

        const toHide = document.getElementsByClassName(option.value);
        for (let i = 0; i < toHide.length; i++) {
            toHide[i].classList.add('hidden');
        }
    });
}

function parseCommandLineArguments(): ArgsMap {
    const args = process.argv.slice(2); // Skip node and script paths
    const argsMap: ArgsMap = {};
    args.forEach((arg) => {
        const [key, value] = arg.split('=');
        if (key.startsWith('--')) {
            const name = key.substring(2);
            argsMap[name] = value;
            // User may provide a help arg without any value
            if (name.toLowerCase() === 'help' && !value) {
                argsMap[name] = 'true';
            }
        }
    });
    return argsMap;
}

